//! Verifies watcher-neutral synchronization and feedback suppression.
use scriberig_core::{EntityId, SnapshotId};
use sr_projection::{ProjectionRef, ProjectionStatus, SemanticStateRef};
use sr_projection_fs::{
    ArtifactMaterializationMember, ArtifactMaterializationPlan, ArtifactMaterializationReceipt,
    ArtifactMaterializationState, ArtifactMemberReceipt, FileSystem, LocalFileSystem,
    MemorySyncStore, Observation, ProjectionLocation, ProjectionOwnership, SyncCoordinator,
    SyncState, digest_bytes, inspect_observation,
};
use std::fs;

mod common;

/// Checks self-generated bytes converge without invoking an import path.
#[test]
fn self_write_event_is_synchronized() {
    let root = std::env::temp_dir().join(format!("scriberig-observe-{}", std::process::id()));
    let _ = fs::create_dir_all(&root);
    let path = root.join("x");
    let io = LocalFileSystem;
    io.write_atomic(&path, b"same").expect("write");
    let location = ProjectionLocation::new(&path);
    let projection = ProjectionRef(EntityId::from_bytes([1; 16]));
    let mut store = MemorySyncStore::default();
    store.put(SyncState::new(
        projection,
        common::baseline("text", SnapshotId::new([2; 32]), &[], b"same"),
        location.clone(),
        ProjectionOwnership::ManagedEditable,
        SemanticStateRef(SnapshotId::new([2; 32])),
        ProjectionStatus::ExternallyModified,
    ));
    assert_eq!(
        inspect_observation(&io, &mut store, &Observation::Modified(location)).expect("observe"),
        Some(ProjectionStatus::Synchronized)
    );
    let _ = fs::remove_dir_all(root);
}

/// Suppresses only watcher events for artifact members confirmed committed by the receipt.
#[test]
fn artifact_receipt_suppresses_only_committed_member_observations() {
    let root =
        std::env::temp_dir().join(format!("scriberig-artifact-observe-{}", std::process::id()));
    fs::create_dir_all(&root).expect("create project");
    let io = LocalFileSystem;
    io.write_atomic(&root.join("written.bin"), b"new")
        .expect("write committed member");
    io.write_atomic(&root.join("failed.bin"), b"new")
        .expect("write untracked member");
    let snapshot = SnapshotId::new([7; 32]);
    let mut store = MemorySyncStore::default();
    for (index, name) in ["written.bin", "failed.bin"].into_iter().enumerate() {
        store.put(SyncState::new(
            ProjectionRef(EntityId::from_bytes(
                [u8::try_from(index).expect("fixture index fits in one byte") + 8; 16],
            )),
            common::baseline("text", snapshot, &[], b"old"),
            ProjectionLocation::new(root.join(name)),
            ProjectionOwnership::ManagedEditable,
            SemanticStateRef(snapshot),
            ProjectionStatus::Synchronized,
        ));
    }
    let artifact = EntityId::from_bytes([9; 16]);
    let plan = ArtifactMaterializationPlan {
        artifact,
        root: root.clone(),
        members: ["written.bin", "failed.bin"]
            .into_iter()
            .map(|name| ArtifactMaterializationMember {
                key: name.into(),
                relative_path: name.into(),
                expected_digest: Some(digest_bytes(b"old")),
                required: true,
                bytes: Some(b"new".to_vec()),
            })
            .collect(),
        opaque_content: Vec::new(),
    };
    let receipt = ArtifactMaterializationReceipt {
        artifact,
        state: ArtifactMaterializationState::RecoverableFailure,
        members: vec![
            ArtifactMemberReceipt {
                key: "written.bin".into(),
                output_digest: Some(digest_bytes(b"new")),
                observed_digest: Some(digest_bytes(b"new")),
                committed: true,
                failure: None,
            },
            ArtifactMemberReceipt {
                key: "failed.bin".into(),
                output_digest: Some(digest_bytes(b"new")),
                observed_digest: None,
                committed: false,
                failure: Some("injected failure".into()),
            },
        ],
        opaque_content: Vec::new(),
    };
    let mut coordinator = SyncCoordinator::new(io, store);
    let mut invalid_receipt = receipt.clone();
    invalid_receipt.members[0].output_digest = Some(digest_bytes(b"different output"));
    assert_eq!(
        coordinator
            .record_artifact_materialization(&plan, &invalid_receipt)
            .expect("ignore mismatched receipt digest"),
        0
    );
    assert_eq!(
        coordinator
            .record_artifact_materialization(&plan, &receipt)
            .expect("persist committed member observation"),
        1
    );
    let written = ProjectionLocation::new(root.join("written.bin"));
    let written_observation = coordinator
        .observe(&Observation::Modified(written))
        .expect("observe committed member")
        .expect("owned projection");
    assert!(written_observation.import.is_none());
    let failed = ProjectionLocation::new(root.join("failed.bin"));
    let failed_observation = coordinator
        .observe(&Observation::Modified(failed))
        .expect("observe uncommitted member")
        .expect("owned projection");
    assert!(failed_observation.import.is_some());
    let _ = fs::remove_dir_all(root);
}

/// Marks a committed artifact deletion missing without scheduling semantic import.
#[test]
fn committed_artifact_deletion_is_not_imported_as_an_external_edit() {
    let root =
        std::env::temp_dir().join(format!("scriberig-artifact-delete-{}", std::process::id()));
    fs::create_dir_all(&root).expect("create project");
    let path = root.join("obsolete.bin");
    fs::write(&path, b"old member").expect("old member");
    let location = ProjectionLocation::new(&path);
    let projection = ProjectionRef(EntityId::from_bytes([17; 16]));
    let snapshot = SnapshotId::new([18; 32]);
    let mut store = MemorySyncStore::default();
    store.put(SyncState::new(
        projection,
        common::baseline("text", snapshot, &[], b"old member"),
        location.clone(),
        ProjectionOwnership::ManagedEditable,
        SemanticStateRef(snapshot),
        ProjectionStatus::Synchronized,
    ));
    let artifact = EntityId::from_bytes([19; 16]);
    let plan = ArtifactMaterializationPlan {
        artifact,
        root: root.clone(),
        members: vec![ArtifactMaterializationMember {
            key: "obsolete".into(),
            relative_path: "obsolete.bin".into(),
            expected_digest: Some(digest_bytes(b"old member")),
            required: true,
            bytes: None,
        }],
        opaque_content: Vec::new(),
    };
    let receipt = ArtifactMaterializationReceipt {
        artifact,
        state: ArtifactMaterializationState::Complete,
        members: vec![ArtifactMemberReceipt {
            key: "obsolete".into(),
            output_digest: None,
            observed_digest: None,
            committed: true,
            failure: None,
        }],
        opaque_content: Vec::new(),
    };
    let mut coordinator = SyncCoordinator::new(LocalFileSystem, store);
    assert_eq!(
        coordinator
            .record_artifact_materialization(&plan, &receipt)
            .expect("record deletion receipt"),
        1
    );

    let observed = coordinator
        .observe(&Observation::Removed(location))
        .expect("observe committed removal")
        .expect("tracked projection");

    assert_eq!(observed.status, ProjectionStatus::Missing);
    assert!(observed.import.is_none());
    fs::remove_dir_all(root).expect("remove fixture");
}

/// Checks missing files become Missing without semantic deletion.
#[test]
fn removal_is_not_semantic_deletion() {
    let location = ProjectionLocation::new("missing.txt");
    let mut store = MemorySyncStore::default();
    store.put(SyncState::new(
        ProjectionRef(EntityId::from_bytes([3; 16])),
        common::baseline("text", SnapshotId::new([4; 32]), &[], b"old"),
        location.clone(),
        ProjectionOwnership::ManagedEditable,
        SemanticStateRef(SnapshotId::new([4; 32])),
        ProjectionStatus::Synchronized,
    ));
    let io = LocalFileSystem;
    assert_eq!(
        inspect_observation(&io, &mut store, &Observation::Removed(location)).expect("observe"),
        Some(ProjectionStatus::Missing)
    );
}
